#[derive(Clone, Copy, Debug, PartialEq)]
#[repr(u16)]
pub enum Model6Alg {
    /// For test purposes only
    None = 0,
    AesGmac64 = 1,
    Ecc256 = 2,
}

impl Model6Alg {
    pub fn from_repr(repr: u16) -> Option<Model6Alg> {
        match repr {
            0 => Some(Model6Alg::None),
            1 => Some(Model6Alg::AesGmac64),
            2 => Some(Model6Alg::Ecc256),
            _ => None,
        }
    }
}

/// Short, spec-matching alias for [`Model6Alg`] - only `Model6Alg` (unique per model) reaches the generated C header, since cbindgen has no module system to keep `Alg` distinct from another model's point of the same name.
pub type Alg = Model6Alg;

